package javaBasics1;

public class Variable7_define {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int a;//declare
		a=10;//assign
		System.out.println(a);

		char b='h';//defining
		System.out.println(b);

		String c="a";//define
		System.out.println(c);

		String str ="Yogesh Pole";
		System.out.println(str);

	}

}
